import{_ as o,c as a,o as t,ag as r}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"How to Search Log Files","description":"","frontmatter":{"title":"How to Search Log Files"},"headers":[],"relativePath":"general/how-to-search-log-files.md","filePath":"general/how-to-search-log-files.md","lastUpdated":null}'),i={name:"general/how-to-search-log-files.md"};function s(n,e,l,c,h,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="how-to-search-log-files" tabindex="-1">How to Search Log Files <a class="header-anchor" href="#how-to-search-log-files" aria-label="Permalink to &quot;How to Search Log Files&quot;">​</a></h1><h2 id="how-to-check-and-make-sense-of-logs-on-different-operating-systems" tabindex="-1">How to Check and Make Sense of Logs on Different Operating Systems <a class="header-anchor" href="#how-to-check-and-make-sense-of-logs-on-different-operating-systems" aria-label="Permalink to &quot;How to Check and Make Sense of Logs on Different Operating Systems&quot;">​</a></h2><p>If you need to go back to the guide, click * Cyber Incident Response Guide*</p><h3 id="mobile-ios" tabindex="-1">Mobile: iOS <a class="header-anchor" href="#mobile-ios" aria-label="Permalink to &quot;Mobile: iOS&quot;">​</a></h3><h4 id="use-analytics-improvements" tabindex="-1">Use Analytics &amp; Improvements <a class="header-anchor" href="#use-analytics-improvements" aria-label="Permalink to &quot;Use Analytics &amp; Improvements&quot;">​</a></h4><h2 id="go-to-settings-privacy-analytics-improvements" tabindex="-1">Go to <strong>Settings</strong> &gt; <strong>Privacy</strong> &gt; <strong>Analytics &amp; Improvements</strong>. <a class="header-anchor" href="#go-to-settings-privacy-analytics-improvements" aria-label="Permalink to &quot;Go to **Settings** &gt; **Privacy** &gt; **Analytics &amp; Improvements**.&quot;">​</a></h2><h2 id="select-analytics-data-to-view-system-and-app-logs" tabindex="-1">Select <strong>Analytics Data</strong> to view system and app logs. <a class="header-anchor" href="#select-analytics-data-to-view-system-and-app-logs" aria-label="Permalink to &quot;Select **Analytics Data** to view system and app logs.&quot;">​</a></h2><h4 id="identify-suspicious-activity" tabindex="-1">Identify Suspicious Activity <a class="header-anchor" href="#identify-suspicious-activity" aria-label="Permalink to &quot;Identify Suspicious Activity&quot;">​</a></h4><h2 id="look-for-entries-such-as-sysdiagnose-or-stacks-appname-indicating-app-crashes-or-system-issues" tabindex="-1">Look for entries such as <code>sysdiagnose</code> or <code>stacks+appName</code>, indicating app crashes or system issues. <a class="header-anchor" href="#look-for-entries-such-as-sysdiagnose-or-stacks-appname-indicating-app-crashes-or-system-issues" aria-label="Permalink to &quot;Look for entries such as `sysdiagnose` or `stacks+appName`, indicating app crashes or system issues.&quot;">​</a></h2><h2 id="search-for-terms-like-privacy-location-or-permission-to-find-logs-related-to-privacy-settings-changes" tabindex="-1">Search for terms like <code>privacy</code>, <code>location</code>, or <code>permission</code> to find logs related to privacy settings changes. <a class="header-anchor" href="#search-for-terms-like-privacy-location-or-permission-to-find-logs-related-to-privacy-settings-changes" aria-label="Permalink to &quot;Search for terms like `privacy`, `location`, or `permission` to find logs related to privacy settings changes.&quot;">​</a></h2><h2 id="check-for-any-entries-with-daemon-or-process-indicating-background-activities" tabindex="-1">Check for any entries with <code>daemon</code> or <code>process</code> indicating background activities. <a class="header-anchor" href="#check-for-any-entries-with-daemon-or-process-indicating-background-activities" aria-label="Permalink to &quot;Check for any entries with `daemon` or `process` indicating background activities.&quot;">​</a></h2><h3 id="mobile-android" tabindex="-1">Mobile: Android <a class="header-anchor" href="#mobile-android" aria-label="Permalink to &quot;Mobile: Android&quot;">​</a></h3><h4 id="enable-developer-options" tabindex="-1">Enable Developer Options <a class="header-anchor" href="#enable-developer-options" aria-label="Permalink to &quot;Enable Developer Options&quot;">​</a></h4><h2 id="go-to-settings-about-phone" tabindex="-1">Go to <strong>Settings</strong> &gt; <strong>About phone</strong>. <a class="header-anchor" href="#go-to-settings-about-phone" aria-label="Permalink to &quot;Go to **Settings** &gt; **About phone**.&quot;">​</a></h2><h2 id="tap-build-number-seven-times-to-enable-developer-options" tabindex="-1">Tap <strong>Build number</strong> seven times to enable Developer Options. <a class="header-anchor" href="#tap-build-number-seven-times-to-enable-developer-options" aria-label="Permalink to &quot;Tap **Build number** seven times to enable Developer Options.&quot;">​</a></h2><h4 id="access-logs-through-developer-options" tabindex="-1">Access Logs through Developer Options <a class="header-anchor" href="#access-logs-through-developer-options" aria-label="Permalink to &quot;Access Logs through Developer Options&quot;">​</a></h4><h2 id="go-to-settings-system-developer-options" tabindex="-1">Go to <strong>Settings</strong> &gt; <strong>System</strong> &gt; <strong>Developer options</strong>. <a class="header-anchor" href="#go-to-settings-system-developer-options" aria-label="Permalink to &quot;Go to **Settings** &gt; **System** &gt; **Developer options**.&quot;">​</a></h2><h2 id="scroll-to-debugging-and-select-take-bug-report-or-log-viewer" tabindex="-1">Scroll to <strong>Debugging</strong> and select <strong>Take bug report</strong> or <strong>Log viewer</strong>. <a class="header-anchor" href="#scroll-to-debugging-and-select-take-bug-report-or-log-viewer" aria-label="Permalink to &quot;Scroll to **Debugging** and select **Take bug report** or **Log viewer**.&quot;">​</a></h2><h4 id="check-for-suspicious-activity" tabindex="-1">Check for Suspicious Activity <a class="header-anchor" href="#check-for-suspicious-activity" aria-label="Permalink to &quot;Check for Suspicious Activity&quot;">​</a></h4><h2 id="look-for-frequent-app-crashes-or-unexpected-system-behavior-in-the-logs" tabindex="-1">Look for frequent app crashes or unexpected system behavior in the logs. <a class="header-anchor" href="#look-for-frequent-app-crashes-or-unexpected-system-behavior-in-the-logs" aria-label="Permalink to &quot;Look for frequent app crashes or unexpected system behavior in the logs.&quot;">​</a></h2><h2 id="identify-any-unusual-network-activities-or-connection-attempts" tabindex="-1">Identify any unusual network activities or connection attempts. <a class="header-anchor" href="#identify-any-unusual-network-activities-or-connection-attempts" aria-label="Permalink to &quot;Identify any unusual network activities or connection attempts.&quot;">​</a></h2><h2 id="check-for-logs-indicating-changes-in-security-settings-or-permissions-granted-to-unfamiliar-apps" tabindex="-1">Check for logs indicating changes in security settings or permissions granted to unfamiliar apps. <a class="header-anchor" href="#check-for-logs-indicating-changes-in-security-settings-or-permissions-granted-to-unfamiliar-apps" aria-label="Permalink to &quot;Check for logs indicating changes in security settings or permissions granted to unfamiliar apps.&quot;">​</a></h2><h2 id="look-for-repeated-attempts-to-access-secure-features-or-data-without-authorization" tabindex="-1">Look for repeated attempts to access secure features or data without authorization. <a class="header-anchor" href="#look-for-repeated-attempts-to-access-secure-features-or-data-without-authorization" aria-label="Permalink to &quot;Look for repeated attempts to access secure features or data without authorization.&quot;">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><h4 id="open-the-event-viewer" tabindex="-1">Open the Event Viewer <a class="header-anchor" href="#open-the-event-viewer" aria-label="Permalink to &quot;Open the Event Viewer&quot;">​</a></h4><h2 id="press-the-windows-key-r-to-open-the-run-dialog-box" tabindex="-1">Press the Windows key + R to open the Run dialog box. <a class="header-anchor" href="#press-the-windows-key-r-to-open-the-run-dialog-box" aria-label="Permalink to &quot;Press the Windows key + R to open the Run dialog box.&quot;">​</a></h2><h2 id="type-eventvwr-msc-and-press-enter" tabindex="-1">Type <code>eventvwr.msc</code> and press Enter. <a class="header-anchor" href="#type-eventvwr-msc-and-press-enter" aria-label="Permalink to &quot;Type `eventvwr.msc` and press Enter.&quot;">​</a></h2><h2 id="the-event-viewer-will-open" tabindex="-1">The Event Viewer will open. <a class="header-anchor" href="#the-event-viewer-will-open" aria-label="Permalink to &quot;The Event Viewer will open.&quot;">​</a></h2><h4 id="look-for-error-or-warning-logs-related-to-security" tabindex="-1">Look for Error or Warning Logs Related to Security <a class="header-anchor" href="#look-for-error-or-warning-logs-related-to-security" aria-label="Permalink to &quot;Look for Error or Warning Logs Related to Security&quot;">​</a></h4><h2 id="navigate-to-windows-logs-security" tabindex="-1">Navigate to <strong>Windows Logs</strong> &gt; <strong>Security</strong>. <a class="header-anchor" href="#navigate-to-windows-logs-security" aria-label="Permalink to &quot;Navigate to **Windows Logs** &gt; **Security**.&quot;">​</a></h2><h2 id="sort-the-logs-by-event-id-level-or-source" tabindex="-1">Sort the logs by Event ID, Level, or Source. <a class="header-anchor" href="#sort-the-logs-by-event-id-level-or-source" aria-label="Permalink to &quot;Sort the logs by Event ID, Level, or Source.&quot;">​</a></h2><h2 id="look-for-event-ids" tabindex="-1">Look for Event IDs: <a class="header-anchor" href="#look-for-event-ids" aria-label="Permalink to &quot;Look for Event IDs:&quot;">​</a></h2><ul><li><code>4624</code> (successful logon),</li><li><code>4625</code> (failed logon),</li><li><code>4648</code> (explicit login).</li></ul><h4 id="search-for-suspicious-activity" tabindex="-1">Search for Suspicious Activity <a class="header-anchor" href="#search-for-suspicious-activity" aria-label="Permalink to &quot;Search for Suspicious Activity&quot;">​</a></h4><h2 id="look-for-repeated-failed-login-attempts-from-the-same-source-ip" tabindex="-1">Look for repeated failed login attempts from the same source IP. <a class="header-anchor" href="#look-for-repeated-failed-login-attempts-from-the-same-source-ip" aria-label="Permalink to &quot;Look for repeated failed login attempts from the same source IP.&quot;">​</a></h2><h2 id="look-for-logon-attempts-from-unfamiliar-locations-or-at-unusual-times" tabindex="-1">Look for logon attempts from unfamiliar locations or at unusual times. <a class="header-anchor" href="#look-for-logon-attempts-from-unfamiliar-locations-or-at-unusual-times" aria-label="Permalink to &quot;Look for logon attempts from unfamiliar locations or at unusual times.&quot;">​</a></h2><h2 id="look-for-logs-indicating-changes-to-security-settings-or-software" tabindex="-1">Look for logs indicating changes to security settings or software. <a class="header-anchor" href="#look-for-logs-indicating-changes-to-security-settings-or-software" aria-label="Permalink to &quot;Look for logs indicating changes to security settings or software.&quot;">​</a></h2><h2 id="look-for-logs-indicating-new-software-installations-or-changes-to-existing-software" tabindex="-1">Look for logs indicating new software installations or changes to existing software. <a class="header-anchor" href="#look-for-logs-indicating-new-software-installations-or-changes-to-existing-software" aria-label="Permalink to &quot;Look for logs indicating new software installations or changes to existing software.&quot;">​</a></h2><h3 id="macos" tabindex="-1">MacOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;MacOS&quot;">​</a></h3><h4 id="open-console" tabindex="-1">Open Console <a class="header-anchor" href="#open-console" aria-label="Permalink to &quot;Open Console&quot;">​</a></h4><h2 id="launch-the-console-application-from-the-utilities-folder-within-the-applications-folder" tabindex="-1">Launch the <strong>Console</strong> application from the <strong>Utilities</strong> folder within the <strong>Applications</strong> folder. <a class="header-anchor" href="#launch-the-console-application-from-the-utilities-folder-within-the-applications-folder" aria-label="Permalink to &quot;Launch the **Console** application from the **Utilities** folder within the **Applications** folder.&quot;">​</a></h2><h4 id="look-for-error-or-warning-logs-related-to-security-1" tabindex="-1">Look for Error or Warning Logs Related to Security <a class="header-anchor" href="#look-for-error-or-warning-logs-related-to-security-1" aria-label="Permalink to &quot;Look for Error or Warning Logs Related to Security&quot;">​</a></h4><h2 id="check-logs-related-to-security-software-such-as-antivirus-or-firewall" tabindex="-1">Check logs related to security software such as antivirus or firewall. <a class="header-anchor" href="#check-logs-related-to-security-software-such-as-antivirus-or-firewall" aria-label="Permalink to &quot;Check logs related to security software such as antivirus or firewall.&quot;">​</a></h2><h2 id="search-for-logs-with-keywords-like-error-or-warning" tabindex="-1">Search for logs with keywords like <code>error</code> or <code>warning</code>. <a class="header-anchor" href="#search-for-logs-with-keywords-like-error-or-warning" aria-label="Permalink to &quot;Search for logs with keywords like `error` or `warning`.&quot;">​</a></h2><h4 id="search-for-suspicious-activity-1" tabindex="-1">Search for Suspicious Activity <a class="header-anchor" href="#search-for-suspicious-activity-1" aria-label="Permalink to &quot;Search for Suspicious Activity&quot;">​</a></h4><h2 id="look-for-repeated-failed-logon-attempts-from-the-same-source-ip" tabindex="-1">Look for repeated failed logon attempts from the same source IP. <a class="header-anchor" href="#look-for-repeated-failed-logon-attempts-from-the-same-source-ip" aria-label="Permalink to &quot;Look for repeated failed logon attempts from the same source IP.&quot;">​</a></h2><h2 id="look-for-logon-attempts-from-unfamiliar-locations-or-at-unusual-times-1" tabindex="-1">Look for logon attempts from unfamiliar locations or at unusual times. <a class="header-anchor" href="#look-for-logon-attempts-from-unfamiliar-locations-or-at-unusual-times-1" aria-label="Permalink to &quot;Look for logon attempts from unfamiliar locations or at unusual times.&quot;">​</a></h2><h2 id="check-logs-indicating-changes-to-security-settings-or-software" tabindex="-1">Check logs indicating changes to security settings or software. <a class="header-anchor" href="#check-logs-indicating-changes-to-security-settings-or-software" aria-label="Permalink to &quot;Check logs indicating changes to security settings or software.&quot;">​</a></h2><h2 id="look-for-logs-indicating-new-software-installations-or-changes-to-existing-software-1" tabindex="-1">Look for logs indicating new software installations or changes to existing software. <a class="header-anchor" href="#look-for-logs-indicating-new-software-installations-or-changes-to-existing-software-1" aria-label="Permalink to &quot;Look for logs indicating new software installations or changes to existing software.&quot;">​</a></h2><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><h4 id="open-terminal" tabindex="-1">Open Terminal <a class="header-anchor" href="#open-terminal" aria-label="Permalink to &quot;Open Terminal&quot;">​</a></h4><h2 id="launch-the-terminal-application" tabindex="-1">Launch the <strong>Terminal</strong> application. <a class="header-anchor" href="#launch-the-terminal-application" aria-label="Permalink to &quot;Launch the **Terminal** application.&quot;">​</a></h2><h4 id="look-for-error-or-warning-logs-related-to-security-2" tabindex="-1">Look for Error or Warning Logs Related to Security <a class="header-anchor" href="#look-for-error-or-warning-logs-related-to-security-2" aria-label="Permalink to &quot;Look for Error or Warning Logs Related to Security&quot;">​</a></h4><h2 id="use-the-command" tabindex="-1">Use the command: <a class="header-anchor" href="#use-the-command" aria-label="Permalink to &quot;Use the command:&quot;">​</a></h2><p><code>sudo grep -E &#39;error|warning&#39; /var/log/auth.log</code> to view security logs.</p><h4 id="check-users" tabindex="-1">Check Users <a class="header-anchor" href="#check-users" aria-label="Permalink to &quot;Check Users&quot;">​</a></h4><h2 id="use-the-command-1" tabindex="-1">Use the command: <a class="header-anchor" href="#use-the-command-1" aria-label="Permalink to &quot;Use the command:&quot;">​</a></h2><p><code>sudo getent passwd | grep &#39;/home&#39; | cut -d: -f1</code> to see all users with a home directory.</p><h2 id="use-the-command-2" tabindex="-1">Use the command: <a class="header-anchor" href="#use-the-command-2" aria-label="Permalink to &quot;Use the command:&quot;">​</a></h2><p><code>sudo getent passwd | cut -d: -f1</code> to see all users, even those without a home directory.</p><h4 id="search-for-suspicious-activity-2" tabindex="-1">Search for Suspicious Activity <a class="header-anchor" href="#search-for-suspicious-activity-2" aria-label="Permalink to &quot;Search for Suspicious Activity&quot;">​</a></h4><h2 id="look-for-repeated-failed-login-attempts-from-the-same-source-ip-1" tabindex="-1">Look for repeated failed login attempts from the same source IP. <a class="header-anchor" href="#look-for-repeated-failed-login-attempts-from-the-same-source-ip-1" aria-label="Permalink to &quot;Look for repeated failed login attempts from the same source IP.&quot;">​</a></h2><h2 id="look-for-logon-attempts-from-unfamiliar-locations-or-at-unusual-times-2" tabindex="-1">Look for logon attempts from unfamiliar locations or at unusual times. <a class="header-anchor" href="#look-for-logon-attempts-from-unfamiliar-locations-or-at-unusual-times-2" aria-label="Permalink to &quot;Look for logon attempts from unfamiliar locations or at unusual times.&quot;">​</a></h2><h2 id="check-logs-indicating-changes-to-security-settings-or-software-1" tabindex="-1">Check logs indicating changes to security settings or software. <a class="header-anchor" href="#check-logs-indicating-changes-to-security-settings-or-software-1" aria-label="Permalink to &quot;Check logs indicating changes to security settings or software.&quot;">​</a></h2><h2 id="look-for-logs-indicating-new-software-installations-or-changes-to-existing-software-2" tabindex="-1">Look for logs indicating new software installations or changes to existing software. <a class="header-anchor" href="#look-for-logs-indicating-new-software-installations-or-changes-to-existing-software-2" aria-label="Permalink to &quot;Look for logs indicating new software installations or changes to existing software.&quot;">​</a></h2>',65)])])}const f=o(i,[["render",s]]);export{g as __pageData,f as default};
